import os, json

N = 26

def read_pairs_csv(path):
    s = set()
    try:
        with open(path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line[0].isalpha():
                    continue
                parts = [p.strip() for p in line.split(',')]
                if len(parts) >= 2:
                    try:
                        i = int(parts[0]); j = int(parts[1])
                    except Exception:
                        continue
                    if i > j: i, j = j, i
                    s.add((i, j))
    except Exception:
        return None
    return s

def read_boundary_csv(path):
    alias = {'xL':'xmin','xR':'xmax','yB':'ymin','yT':'ymax',
             'xmin':'xmin','xmax':'xmax','ymin':'ymin','ymax':'ymax'}
    s = set()
    try:
        with open(path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                parts = [p.strip() for p in line.split(',')]
                if len(parts) >= 2:
                    try:
                        i = int(parts[0])
                    except Exception:
                        continue
                    kind = alias.get(parts[1], parts[1])
                    s.add((i, kind))
    except Exception:
        return None
    return s

def jacc(a, b):
    if a is None or b is None: return None, None, None
    inter = len(a & b); uni = len(a | b)
    j = (inter/uni) if uni else 1.0
    return j, inter, uni

def construct_packing():
    results = {}
    for n in range(25, 31):
        a_dir = f'storage/Aletheia/nmap/n{n}'
        s_dir = f'storage/Scientia/nmap/n{n}'
        a_bp = os.path.join(a_dir, 'active_boundary_tol1e8.csv')
        a_pp = os.path.join(a_dir, 'active_pairs_tol1e8.csv')
        s_bp = os.path.join(s_dir, 'active_boundary_tol1e8.csv')
        s_pp = os.path.join(s_dir, 'active_pairs_tol1e8.csv')

        if (not os.path.exists(a_bp)) or (not os.path.exists(a_pp)) or (not os.path.exists(s_bp)) or (not os.path.exists(s_pp)):
            continue

        Ab = read_boundary_csv(a_bp); Ap = read_pairs_csv(a_pp)
        Sb = read_boundary_csv(s_bp); Sp = read_pairs_csv(s_pp)
        jb, ibi, ubu = jacc(Ab, Sb)
        jp, ipi, upu = jacc(Ap, Sp)
        results[str(n)] = {
            'boundary_jaccard': jb,
            'pairs_jaccard': jp,
            'boundary_counts': {'inter': ibi, 'union': ubu},
            'pairs_counts': {'inter': ipi, 'union': upu},
            'paths': {'A': a_dir, 'S': s_dir}
        }

    try:
        os.makedirs('storage/noesis/nmap', exist_ok=True)
        with open('storage/noesis/nmap/jaccards_as_tol1e8.json', 'w') as f:
            json.dump({'tol': 1e-8, 'ns': list(results.keys()), 'results': results}, f, indent=2)
    except Exception:
        pass

    # Return baseline unchanged
    try:
        import numpy as np
        c = np.loadtxt('storage/noesis/latest_centers.txt', dtype=float).reshape(N,2)
        r = np.loadtxt('storage/noesis/latest_radii.txt', dtype=float).reshape(N,)
    except Exception:
        import numpy as np
        coords = [0.1,0.3,0.5,0.7,0.9]
        centers = np.array([[x,y] for x in coords for y in coords], float)
        hole = np.array([0.2,0.2], float)
        centers = np.vstack([centers, hole])
        r0 = 0.1 - 1e-8
        d = float(np.linalg.norm(hole - np.array([0.1,0.1])))
        radii = np.array([r0]*25 + [d - r0 - 1e-8], float)
        c, r = centers, radii
    return c.astype(float), r.astype(float)
